'use strict';

// Builds dist/tamemark.browser.js from src/core.js. The bundle exposes
// window.tamemark.render and does not include the footnotes extension.
const fs = require('node:fs');
const path = require('node:path');

const root = path.resolve(__dirname, '..');
const core = fs.readFileSync(path.join(root, 'src', 'core.js'), 'utf8')
  .replace("'use strict';\n", '')
  .replace('module.exports = { render, inline };\n', '');
const bundle = [
  '/* tamemark browser bundle, generated by scripts/build-browser.js */',
  '(function (global) {',
  "  'use strict';",
  core.trim().split('\n').map((line) => (line ? `  ${line}` : line)).join('\n'),
  '  global.tamemark = { render: (markdown, options = {}) => render(markdown, { ...options, extensions: [] }) };',
  "})(typeof window !== 'undefined' ? window : globalThis);",
  '',
].join('\n');
fs.writeFileSync(path.join(root, 'dist', 'tamemark.browser.js'), bundle);
